using NUnit.Framework;using System;using System.IO;using System.Text;using CommunityPoke.UnityGit;
public class GitCoreTests { [Test] public void HashKnownBlob(){Assert.AreEqual("ce013625030ba8dba906f756967f9e9ca394464a",GitHash.Compute("blob",Encoding.UTF8.GetBytes("hello world\n")));} [Test] public void LooseObjectRoundTrip(){var d=Path.Combine(Path.GetTempPath(),Guid.NewGuid().ToString());var s=new LooseObjectStore(Path.Combine(d,".git"));var b=new Blob(Encoding.UTF8.GetBytes("payload"));var h=s.Write(b);var r=s.Read(h);Assert.AreEqual("blob",r.type);CollectionAssert.AreEqual(b.Data,r.data);Directory.Delete(d,true);} [Test] public void CreateCommit(){var d=Path.Combine(Path.GetTempPath(),Guid.NewGuid().ToString());var r=Repository.Init(d);File.WriteAllText(Path.Combine(d,"a.txt"),"hello");r.Add("a.txt");var h=r.Commit("first");Assert.AreEqual(40,h.Length);Assert.IsTrue(System.Linq.Enumerable.Any(r.Log()));Directory.Delete(d,true);} }